
var KalturaGoogleIdpService={attach:function(idToken){var kparams=new Object();kparams.idToken=idToken;return new KalturaRequestBuilder("googleidp","attach",kparams);},detach:function(){var kparams=new Object();return new KalturaRequestBuilder("googleidp","detach",kparams);},getServiceId:function(){var kparams=new Object();return new KalturaRequestBuilder("googleidp","getServiceId",kparams);},isAttached:function(){var kparams=new Object();return new KalturaRequestBuilder("googleidp","isAttached",kparams);},login:function(partnerId,idToken,extraParams,udid){if(!extraParams)
extraParams=null;if(!udid)
udid=null;var kparams=new Object();kparams.partnerId=partnerId;kparams.idToken=idToken;if(extraParams!=null)
kparams.extraParams=extraParams;kparams.udid=udid;return new KalturaRequestBuilder("googleidp","login",kparams);},setServiceId:function(serviceId){var kparams=new Object();kparams.serviceId=serviceId;return new KalturaRequestBuilder("googleidp","setServiceId",kparams);}}